import java.util.HashMap;
import java.util.Map;

public class BrokenCounter {
    static Map<String, Integer> counts = new HashMap<>();

    static void increment(String key) {
        Integer current = counts.get(key);
        int next = (current == null) ? 1 : current + 1;
        counts.put(key, next);
    }

    public static void main(String[] args) throws InterruptedException {
        Runnable task = () -> {
            for (int i = 0; i < 100000; i++) {
                increment("clicks");
            }
        };
        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);
        t1.start(); t2.start();
        t1.join(); t2.join();
        // Expected 200000, actual is usually lower, or the map
        // throws an exception during an internal resize.
        System.out.println(counts.get("clicks"));
    }
}

