#include <iostream>
#include <string>
#include <thread>
#include <unordered_map>
using namespace std;

unordered_map<string, int> counts;

void increment(const string& key) {
    auto it = counts.find(key);
    int next = (it == counts.end()) ? 1 : it->second + 1;
    counts[key] = next;
}

void worker() {
    for (int i = 0; i < 100000; i++) {
        increment("clicks");
    }
}

int main() {
    thread t1(worker);
    thread t2(worker);
    t1.join();
    t2.join();
    // Expected 200000, actual is usually lower, or the program
    // crashes outright: std::unordered_map has no protection at
    // all against two threads rehashing or writing at once.
    cout << counts["clicks"] << endl;
    return 0;
}

