import java.util.concurrent.ConcurrentHashMap;

public class ConcurrentMapCounter {
    static ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();

    static void increment(String key) {
        // merge is atomic: no external lock needed, and unrelated
        // keys never block each other.
        counts.merge(key, 1, Integer::sum);
    }

    public static void main(String[] args) throws InterruptedException {
        Runnable task = () -> {
            for (int i = 0; i < 100000; i++) increment("clicks");
        };
        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);
        t1.start(); t2.start();
        t1.join(); t2.join();
        System.out.println(counts.get("clicks")); // always 200000
    }
}

