#include <array>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <unordered_map>
using namespace std;

// C++ has no built in ConcurrentHashMap. The idiomatic fallback is
// to stripe the map across several independent locks, the same
// lock striping idea ConcurrentHashMap uses internally per bucket.
constexpr int STRIPES = 16;
array<mutex, STRIPES> stripeLocks;
array<unordered_map<string, int>, STRIPES> shards;

int stripeFor(const string& key) {
    return static_cast<int>(hash<string>{}(key) % STRIPES);
}

void increment(const string& key) {
    int s = stripeFor(key);
    lock_guard<mutex> lock(stripeLocks[s]);
    shards[s][key]++; // unrelated keys in other stripes never wait
}

int getCount(const string& key) {
    int s = stripeFor(key);
    lock_guard<mutex> lock(stripeLocks[s]);
    auto it = shards[s].find(key);
    return it == shards[s].end() ? 0 : it->second;
}

void worker() {
    for (int i = 0; i < 100000; i++) increment("clicks");
}

int main() {
    thread t1(worker);
    thread t2(worker);
    t1.join();
    t2.join();
    cout << getCount("clicks") << endl; // always 200000
    return 0;
}

