#include <functional>
#include <iostream>
#include <memory>
#include <mutex>
#include <vector>
using namespace std;

// C++ has no CopyOnWriteArrayList. The closest idiom holds a lock
// only long enough to swap in a freshly copied vector, then lets
// readers iterate a snapshot without ever holding the lock.
class ListenerRegistry {
public:
    void subscribe(function<void()> listener) {
        lock_guard<mutex> lock(mtx);
        auto copy = make_shared<vector<function<void()>>>(*listeners);
        copy->push_back(listener); // rare, pays the copy cost
        listeners = copy;
    }

    void publish() {
        // Grab the current snapshot; a concurrent subscribe() swaps
        // in a whole new vector rather than mutating this one.
        shared_ptr<vector<function<void()>>> snapshot;
        {
            lock_guard<mutex> lock(mtx);
            snapshot = listeners;
        }
        for (auto& listener : *snapshot) {
            listener();
        }
    }

private:
    mutex mtx;
    shared_ptr<vector<function<void()>>> listeners = make_shared<vector<function<void()>>>();
};

