import threading

class CacheExample:
    def __init__(self):
        self._lock = threading.Lock()
        self._cache = {}

    def read(self, key):
        # A short critical section keeps contention low even though
        # Python lacks a built in concurrent map.
        with self._lock:
            return self._cache.get(key)

    def refresh(self, key, new_value):
        with self._lock:
            self._cache[key] = new_value

