#include <iostream>
#include <mutex>
#include <string>
#include <unordered_map>
using namespace std;

class CacheExample {
public:
    string read(const string& key) {
        // A short critical section keeps contention low even though
        // C++ has no built in concurrent map either.
        lock_guard<mutex> lock(mtx);
        auto it = cache.find(key);
        return it == cache.end() ? "" : it->second;
    }

    void refresh(const string& key, const string& newValue) {
        lock_guard<mutex> lock(mtx);
        cache[key] = newValue; // isolated by the same short lock
    }

private:
    mutex mtx;
    unordered_map<string, string> cache;
};
